import{_ as n,o as e,c as s,ag as t}from"./chunks/framework.BcZEdlUI.js";const u=JSON.parse('{"title":"ADR-003: 事件驱动 + IoC 容器架构","description":"","frontmatter":{},"headers":[],"relativePath":"adr/003-event-driven-ioc-architecture.md","filePath":"adr/003-event-driven-ioc-architecture.md","lastUpdated":1781581339000}'),i={name:"adr/003-event-driven-ioc-architecture.md"};function l(r,a,o,d,p,c){return e(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="adr-003-事件驱动-ioc-容器架构" tabindex="-1">ADR-003: 事件驱动 + IoC 容器架构 <a class="header-anchor" href="#adr-003-事件驱动-ioc-容器架构" aria-label="Permalink to &quot;ADR-003: 事件驱动 + IoC 容器架构&quot;">​</a></h1><ul><li><strong>状态</strong>: ✅ Accepted</li><li><strong>日期</strong>: 2026-06-04</li><li><strong>作者</strong>: 架构团队</li><li><strong>关联版本</strong>: v1.0.0 ~ v2.0.0</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>SceneFab 作为多功能桌面应用，模块众多（UI / 流水线 / 服务 / 数据 / 平台），需要清晰的模块解耦方案。</p><p>候选方案：</p><ol><li><strong>事件驱动 + IoC 容器</strong>（EventBus + ServiceContainer）</li><li><strong>直接依赖调用</strong>（模块互相 import）</li><li><strong>回调函数 + 单例</strong></li></ol><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><p>采用 <strong>EventBus（事件驱动）+ ServiceContainer（IoC 容器）</strong> 双引擎架构。</p><h2 id="架构图" tabindex="-1">架构图 <a class="header-anchor" href="#架构图" aria-label="Permalink to &quot;架构图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                UI Layer (PySide6)                      │</span></span>
<span class="line"><span>│   ┌──────────────┐  ┌──────────────┐  ┌─────────────┐  │</span></span>
<span class="line"><span>│   │ MainWindow   │  │ Workbench    │  │ Tray        │  │</span></span>
<span class="line"><span>│   │              │  │ Pages        │  │ Manager     │  │</span></span>
<span class="line"><span>│   └──────┬───────┘  └──────┬───────┘  └──────┬──────┘  │</span></span>
<span class="line"><span>│          │ Signal/Slot     │                  │        │</span></span>
<span class="line"><span>│          └─────────────────┼──────────────────┘        │</span></span>
<span class="line"><span>│                            ▼                           │</span></span>
<span class="line"><span>│           ┌─────────────────────────────┐             │</span></span>
<span class="line"><span>│           │      ServiceContainer       │             │</span></span>
<span class="line"><span>│           │   (IoC: 生命周期/依赖管理)    │             │</span></span>
<span class="line"><span>│           └──────────┬──────────────────┘             │</span></span>
<span class="line"><span>│                      ▼                                 │</span></span>
<span class="line"><span>│           ┌─────────────────────────────┐             │</span></span>
<span class="line"><span>│           │     Services (业务逻辑)      │             │</span></span>
<span class="line"><span>│           │  ai/ video/ audio/ export/  │             │</span></span>
<span class="line"><span>│           │  orchestration/            │             │</span></span>
<span class="line"><span>│           └──────┬──────────────────┬──┘             │</span></span>
<span class="line"><span>│                  │                  │                  │</span></span>
<span class="line"><span>│                  ▼                  ▼                  │</span></span>
<span class="line"><span>│         ┌──────────────┐   ┌──────────────────┐        │</span></span>
<span class="line"><span>│         │   EventBus   │   │  Models + Utils  │        │</span></span>
<span class="line"><span>│         │  (松耦合通信) │   │  (数据 + 工具)    │        │</span></span>
<span class="line"><span>│         └──────────────┘   └──────────────────┘        │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="关键理由" tabindex="-1">关键理由 <a class="header-anchor" href="#关键理由" aria-label="Permalink to &quot;关键理由&quot;">​</a></h2><h3 id="_1-eventbus-解耦模块通信" tabindex="-1">1. EventBus 解耦模块通信 <a class="header-anchor" href="#_1-eventbus-解耦模块通信" aria-label="Permalink to &quot;1. EventBus 解耦模块通信&quot;">​</a></h3><ul><li>业务事件（<code>VideoAnalyzed</code>、<code>NarrationGenerated</code>、<code>VoiceSynthesized</code>）通过 EventBus 广播</li><li>模块不直接依赖其他模块，订阅事件即可响应</li><li>线程安全：内部用 <code>threading.Lock</code> 保护处理器列表</li></ul><h3 id="_2-servicecontainer-统一服务管理" tabindex="-1">2. ServiceContainer 统一服务管理 <a class="header-anchor" href="#_2-servicecontainer-统一服务管理" aria-label="Permalink to &quot;2. ServiceContainer 统一服务管理&quot;">​</a></h3><ul><li><strong>生命周期</strong>：Singleton / Transient / Factory 三种模式</li><li><strong>延迟初始化</strong>：服务按需创建，避免启动时全量加载</li><li><strong>线程安全</strong>：内部锁保护，PySide6 + Worker 线程可安全访问</li><li><strong>可测试性</strong>：测试时可注入 mock 服务</li></ul><h2 id="已注册事件" tabindex="-1">已注册事件 <a class="header-anchor" href="#已注册事件" aria-label="Permalink to &quot;已注册事件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事件名</th><th>触发时机</th><th>典型订阅者</th></tr></thead><tbody><tr><td><code>video_loaded</code></td><td>视频文件导入完成</td><td>UI 状态更新</td></tr><tr><td><code>video_analyzed</code></td><td>视频分析完成</td><td>情感选段模块</td></tr><tr><td><code>segments_selected</code></td><td>情感选段完成</td><td>脚本生成模块</td></tr><tr><td><code>script_generated</code></td><td>解说稿生成完成</td><td>TTS 模块</td></tr><tr><td><code>voice_synthesized</code></td><td>配音合成完成</td><td>字幕对齐模块</td></tr><tr><td><code>captions_aligned</code></td><td>字幕对齐完成</td><td>视频合成模块</td></tr><tr><td><code>video_exported</code></td><td>视频导出完成</td><td>UI 通知 + 审计日志</td></tr><tr><td><code>pipeline_failed</code></td><td>流水线失败</td><td>错误恢复 + UI 通知</td></tr></tbody></table><h2 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h2><ul><li>✅ 模块边界清晰，可独立测试</li><li>✅ UI 与业务逻辑完全解耦</li><li>✅ 未来扩展第三方插件不影响核心</li><li>⚠️ 事件流追踪需要日志（已规划 AuditLogger v2.0）</li><li>⚠️ 过多事件订阅可能影响性能（实测：千级事件下 &lt; 5ms 延迟）</li></ul><h2 id="替代方案探索" tabindex="-1">替代方案探索 <a class="header-anchor" href="#替代方案探索" aria-label="Permalink to &quot;替代方案探索&quot;">​</a></h2><ul><li><strong>直接 import</strong>: 拒绝（耦合严重）</li><li><strong>回调注册</strong>: 评估（太底层，不易调试）</li><li><strong>消息队列 (RabbitMQ/Redis)</strong>: 拒绝（桌面应用无需分布式消息）</li></ul><h2 id="评审" tabindex="-1">评审 <a class="header-anchor" href="#评审" aria-label="Permalink to &quot;评审&quot;">​</a></h2><ul><li>决策贯穿 v1.0 ~ v2.0 三个大版本，已稳定</li><li>在 v2.0 中补充 AuditLogger 以解决事件流追踪问题</li></ul>`,23)])])}const g=n(i,[["render",l]]);export{u as __pageData,g as default};
